    terms = inputs['terms']

    # Initialize p_prev and p
    p_prev = 1
    p = terms[0]

    # Apply recurrence p <- a*p + p_prev for each term after the first
    for i in range(1, len(terms)):
        p_new = terms[i] * p + p_prev
        p_prev = p
        p = p_new

    return float(p)
