def solve(inputs: dict) -> float:
    n = inputs['n']
    k = inputs['k']

    # Create list of people at positions 1 to n
    people = list(range(1, n + 1))

    current_index = 0
    while len(people) > 1:
        # Remove every k-th person (k-1 because we're 0-indexed)
        current_index = (current_index + k - 1) % len(people)
        people.pop(current_index)
        # After removal, current_index points to next person to consider
        if len(people) > 0:
            current_index = current_index % len(people)

    return float(people[0])
