def solve(inputs: dict) -> float:
    remainders = inputs['remainders']
    moduli = inputs['moduli']

    # Chinese Remainder Theorem
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def crt_combine(r1, m1, r2, m2):
        # Solve x ≡ r1 (mod m1) and x ≡ r2 (mod m2)
        gcd, p, q = extended_gcd(m1, m2)
        if (r2 - r1) % gcd != 0:
            return None
        lcm = m1 * m2 // gcd
        x = (r1 + m1 * ((r2 - r1) // gcd) * p) % lcm
        return x, lcm

    # Combine all congruences iteratively
    x = remainders[0]
    m = moduli[0]

    for i in range(1, len(remainders)):
        result = crt_combine(x, m, remainders[i], moduli[i])
        if result is None:
            return -1
        x, m = result

    return float(x)
